Section Call.
Variables (R0 : bvmap 5 word) (M0 : word -> option byte) (model0 : Model) (K : TSet) (LBX : list (Z * Z)) (cr0 : credit).
Variables (o pv S r b z c xb : Z).
Hypothesis HM : PESK.sp_mode P.
Hypothesis Rra0 : getr R0 (reg 1) = Z_to_bv 64 r.
Hypothesis RAok : L5.ra_ok r.
Hypothesis Rsp0 : getr R0 (reg 2) = Z_to_bv 64 S.
Hypothesis Rtp0 : getr R0 (reg 4) = Z_to_bv 64 (pa_tp AD).
Hypothesis K0 : K [].
Hypothesis STK0 : L5C.stk (hl_sptop L) M0 S 12288.
Hypothesis Ho1 : S <= o.
Hypothesis Ho2 : o + 24 <= hl_sptop L.
Hypothesis Ho3 : o mod 8 = 0.
Hypothesis Hpv1 : S <= pv.
Hypothesis Hpv2 : pv + 1 <= hl_sptop L.
Hypothesis Hpv3 : pv + 1 <= o \/ o + 24 <= pv.
Hypothesis A10 : getr R0 (reg 10) = Z_to_bv 64 o.
Hypothesis A11 : getr R0 (reg 11) = Z_to_bv 64 pv.
Hypothesis XB : L5.u8_at RSEGS M0 pv xb.
Hypothesis Hxb : 0 <= xb < 256.
Hypothesis BRLB : PMFR.brange L LBX.
Hypothesis Hzc : 0 <= z <= c.
Hypothesis CAP : PESK.is_cap c.
Hypothesis Hcb : c = 0 -> b = 0.
Hypothesis BLK : 0 < c -> L5.defined M0 b c /\ block_range L b c /\ (PESK.sp_cap P c /\ c <= PESK.sp_nmax P).
Hypothesis W0 : L5.u64_at RSEGS M0 o b.
Hypothesis W8 : L5.u64_at RSEGS M0 (o + 8) (b + z).
Hypothesis W16 : L5.u64_at RSEGS M0 (o + 16) (b + c).
Hypothesis DO0 : L5.defined M0 o 24.
Hypothesis GROW : z = c -> 0 < PESK.cap_next c <= PESK.sp_nmax P
                          /\ (if c =? 0 then 0 else PESK.sp_csz P c) + PESK.sp_csz P (PESK.cap_next c) <= PESK.sp_B P.
Hypothesis CR : PMSP.credit_le (PESK.sink_pot P c) cr0.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (cr' : credit) (b' : Z),
  regs_preserved R0 R' ->
  sink_atP M' o (PESK.sk_push (PESK.SK b z c) b') ->
  L5C.hpres L LBX S (PMSP.pm_scr 0) [(o, 24)] M0 M' ->
  PMSP.credit_keep cr0 cr' (PESK.sink_pot P c) (PESK.sink_pot P (PESK.sk_c (PESK.sk_push (PESK.SK b z c) b'))) ->
  model_but_vm model0 model' -> hi_heap HI (PESK.sink_own (PESK.sk_push (PESK.SK b z c) b') ++ LBX) cr' M' (m_vmmaps model') ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K.

(* [comment removed for export] *)
Definition saves (M : word -> option byte) : Prop :=
  L5.u64_at RSEGS M (S - 8) (bv_unsigned (getr R0 (reg 1))) /\ L5.u64_at RSEGS M (S - 16) (bv_unsigned (getr R0 (reg 8)))
  /\ L5.u64_at RSEGS M (S - 24) (bv_unsigned (getr R0 (reg 9))) /\ L5.u64_at RSEGS M (S - 32) (bv_unsigned (getr R0 (reg 18))).
(* [comment removed for export] *)
Definition inner (M : word -> option byte) (ra : Z) : Prop :=
  L5.u64_at RSEGS M (S - 88) ra /\ L5.u64_at RSEGS M (S - 96) o /\ L5.u64_at RSEGS M (S - 104) pv /\ L5.u64_at RSEGS M (S - 112) (bv_unsigned (getr R0 (reg 18))).
(* [comment removed for export] *)
Definition kept0 (R : bvmap 5 word) : Prop := forall x, In x [3; 4; 19; 20; 21; 22; 23; 24; 25; 26; 27]%nat -> getr R (reg x) = getr R0 (reg x).
Definition mem_ok (M : word -> option byte) : Prop :=
  PMK.ek L LBX S 12288 [(o, 24)] M0 M /\ PMK.dk L LBX S 12288 M0 M /\ L5C.stk (hl_sptop L) M S 12288 /\ L5.defined M o 24.

Lemma regs_back (R1 : bvmap 5 word) :
  getr R1 (reg 2) = Z_to_bv 64 S -> getr R1 (reg 8) = Z_to_bv 64 (bv_unsigned (getr R0 (reg 8))) ->
  getr R1 (reg 9) = Z_to_bv 64 (bv_unsigned (getr R0 (reg 9))) -> getr R1 (reg 18) = Z_to_bv 64 (bv_unsigned (getr R0 (reg 18))) ->
