  getr R (reg 2) = Z_to_bv 64 (S - 80) -> getr R (reg 8) = Z_to_bv 64 o -> getr R (reg 10) = Z_to_bv 64 a0 -> getr R (reg 18) = Z_to_bv 64 (B + c + 1) ->
  0 <= a0 < 2 ^ 64 ->
  kept0 R -> saves M -> mem_ok M ->
  L5.u64_at RSEGS M o B -> L5.u64_at RSEGS M (o + 16) (B + A) ->
  L5.defined M B A -> block_range L B A -> (PESK.sp_cap P A /\ A <= PESK.sp_nmax P) ->
  hi_heap HI ((B, A) :: LBX) cr' M (m_vmmaps model) -> model_but_vm model0 model ->
  PMSP.credit_keep cr0 cr' (PESK.sink_pot P c) (PESK.sink_pot P A) ->
